      "size": "md",
      "audioLinks": "[\n  {\n    \"label\": \"04 - In O’naren.mp3\",\n    \"url\": \"/media/session-audio/a-new-adventure/session-4-1ejBBatfzmzoPas-GrAUgZk9YR5kvNUok.mp3\",\n    \"sourceFileId\": \"1ejBBatfzmzoPas-GrAUgZk9YR5kvNUok\",\n    \"sourceFileName\": \"04 - In O’naren.mp3\",\n    \"sourceUrl\": \"https://drive.google.com/file/d/1ejBBatfzmzoPas-GrAUgZk9YR5kvNUok/view?usp=sharing\"\n  }\n]",
